(function() {
    'use strict';

    class MarketingPrimerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Marketing Primer: La Decisión del Mercado';
            this.version = '1.1.0';
            this._listenersAttached = false;

            this.SEGMENTS = [
                { wtp: 8.00, channels: [0, 1, 2], aw: 0.30, co: 0.20, ac: 0.30, lo: 0.20, size: 0.22 },
                { wtp: 6.00, channels: [0, 1],    aw: 0.25, co: 0.35, ac: 0.25, lo: 0.15, size: 0.25 },
                { wtp: 9.50, channels: [0, 2, 3], aw: 0.20, co: 0.25, ac: 0.20, lo: 0.35, size: 0.20 },
                { wtp: 8.50, channels: [0, 3, 4], aw: 0.20, co: 0.30, ac: 0.20, lo: 0.30, size: 0.18 },
                { wtp: 7.50, channels: [0, 2, 4], aw: 0.15, co: 0.25, ac: 0.30, lo: 0.30, size: 0.15 }
            ];

            this.CHANNELS = [
                { id: 0, cost: 0,     margin: 0,    reach: 0.15 },
                { id: 1, cost: 8000,  margin: 0.05, reach: 0.20 },
                { id: 2, cost: 12000, margin: 0.08, reach: 0.25 },
                { id: 3, cost: 18000, margin: 0.28, reach: 0.45 },
                { id: 4, cost: 15000, margin: 0.12, reach: 0.30 }
            ];

            this.CHANNEL_NAMES = {
                en: ['D2C Online', 'Campus Stores', 'Gyms and Sports Clubs', 'Supermarkets (Wong/Vivanda)', 'Pharmacy Chains'],
                es: ['D2C Online', 'Campus Universitarios', 'Gimnasios y Clubes', 'Supermercados (Wong/Vivanda)', 'Farmacias']
            };

            this.ROUND_TITLES = {
                en: ['Establish Your Territory', 'Gain Ground', 'Consolidate or Bet'],
                es: ['Establece tu Territorio', 'Gana Terreno', 'Consolida o Apuesta']
            };

            this.ROUND_BRIEFINGS_EN = [
                'Sabores del Valle has survived its launch with 4.2% market share in Lima. The angel investor wants a path to 15% within 12 months. This is Q1 — choose your battleground.<br><br>QualiBar dominates the premium segment from the US. Fuerza Natural owns the mass market from Arequipa. Where will you position your Peruvian superfood brand?',
                'Q2 begins. The market is responding to your moves. Review competitor positions and adjust your strategy accordingly.<br><br>Remember: changing your target segment incurs repositioning costs (BEQ −8, budget −S/. 5,000). Consistency builds brand equity.',
                'Final quarter of your growth plan. The investor review is approaching. This is the moment to consolidate your gains or make a bold strategic bet.<br><br>Your cumulative decisions will determine whether Sabores del Valle reaches the 15% market share target.'
            ];

            this.ROUND_BRIEFINGS_ES = [
                'Sabores del Valle ha sobrevivido su lanzamiento con 4.2% de participación en Lima. El inversionista quiere un camino al 15% en 12 meses. Este es el Q1 — elige tu campo de batalla.<br><br>QualiBar domina el segmento premium desde EE.UU. Fuerza Natural controla el mercado masivo desde Arequipa. ¿Dónde vas a posicionar tu marca de superfoods peruanos?',
                'Comienza el Q2. El mercado responde a tus movimientos. Revisa las posiciones competitivas y ajusta tu estrategia.<br><br>Recuerda: cambiar de segmento objetivo tiene costos de reposicionamiento (BEQ −8, presupuesto −S/. 5,000). La consistencia construye brand equity.',
                'Último trimestre del plan de crecimiento. La revisión del inversor se acerca. Este es el momento de consolidar tus logros o hacer una apuesta estratégica fuerte.<br><br>Tus decisiones acumuladas determinarán si Sabores del Valle alcanza la meta del 15% de participación.'
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                // Preserve the event seed across an undo-to-start reset so a replayed
                // game keeps the same random-event scenario (reproducibility). A truly
                // fresh game (empty domainState) gets a new seed.
                var _seed = (state.domainState && typeof state.domainState.eventSeed === 'number') ? state.domainState.eventSeed : Math.random();
                state.domainState = {
                    marketShare: 4.2,
                    beq: 28,
                    currentPrice: 6.50,
                    revenue: 38000,
                    grossMargin: 0.35,
                    repeatRate: 31,
                    satisfaction: 4.1,
                    primarySegment: -1,
                    activeChannels: [0],
                    totalScore: 0,
                    qualibarShare: 18.7,
                    qualibarPrice: 11.90,
                    qualibarBEQ: 71,
                    fuerzaShare: 22.4,
                    fuerzaPrice: 4.20,
                    fuerzaBEQ: 44,
                    hasPackageUpgrade: false,
                    hasNewFormula: false,
                    hasCertification: false,
                    certRoundsLeft: 0,
                    roundsAtPrice: 0,
                    previousSegment: -1,
                    eventSeed: _seed,
                    triggeredEvents: [],
                    marketShareHistory: [],
                    beqHistory: [],
                    revenueHistory: [],
                    scoreHistory: [],
                    performance: { overallScore: 0, grade: 'F', tier: 'tier_reorient', insights: [] }
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    segment: 0,
                    productAmount: 0,
                    productArea: 'none',
                    priceChange: 0,
                    newChannel: -1,
                    budgetAwareness: 15000,
                    budgetContent: 10000,
                    budgetActivation: 10000,
                    budgetLoyalty: 10000,
                    eventChoice: -1
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // NOTE: do NOT call _updateBriefing() here. It rebuilds the event <select>
            // (resetting the choice to -1) right before we read it, which made any
            // round with an active event impossible to submit. The briefing/event
            // panel are refreshed on load, on 'period:submitted', and on langchange.
            var segEl = document.getElementById('segmentSelect');
            if (segEl) decisions.segment = parseInt(segEl.value);

            var paEl = document.getElementById('productAmountSelect');
            if (paEl) decisions.productAmount = parseInt(paEl.value);

            var areaEl = document.getElementById('productAreaSelect');
            if (areaEl) decisions.productArea = areaEl.value;

            var pcEl = document.getElementById('priceChangeSelect');
            if (pcEl) decisions.priceChange = parseFloat(pcEl.value);

            var chEl = document.getElementById('channelSelect');
            if (chEl) decisions.newChannel = parseInt(chEl.value);

            var bAw = document.getElementById('budgetAwareness');
            if (bAw) decisions.budgetAwareness = parseInt(bAw.value) || 0;

            var bCo = document.getElementById('budgetContent');
            if (bCo) decisions.budgetContent = parseInt(bCo.value) || 0;

            var bAc = document.getElementById('budgetActivation');
            if (bAc) decisions.budgetActivation = parseInt(bAc.value) || 0;

            var bLo = document.getElementById('budgetLoyalty');
            if (bLo) decisions.budgetLoyalty = parseInt(bLo.value) || 0;

            var evPanel = document.getElementById('eventPanel');
            var evEl = document.getElementById('eventChoiceSelect');
            if (evEl && evPanel && evPanel.style.display !== 'none') {
                decisions.eventChoice = parseInt(evEl.value);
            } else {
                decisions.eventChoice = -1;
            }

            var totalBudget = decisions.budgetAwareness + decisions.budgetContent + decisions.budgetActivation + decisions.budgetLoyalty;
            if (totalBudget > 45000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_over_warning'), 'warning'
                );
                return false;
            }
            if (decisions.budgetAwareness < 0 || decisions.budgetContent < 0 || decisions.budgetActivation < 0 || decisions.budgetLoyalty < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_negative_warning'), 'warning'
                );
                return false;
            }

            if (decisions.productAmount > 0 && decisions.productArea === 'none') {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('product_area_warning'), 'warning'
                );
                return false;
            }

            var ds = window.mySimulation.state.domainState;
            if (decisions.newChannel >= 0 && ds.activeChannels.indexOf(decisions.newChannel) >= 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('channel_already_warning'), 'warning'
                );
                return false;
            }

            if (evPanel && evPanel.style.display !== 'none' && decisions.eventChoice < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('event_choice_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var seg = this.SEGMENTS[d.segment] || this.SEGMENTS[0];

            var segmentChanged = (ds.primarySegment >= 0 && ds.primarySegment !== d.segment);
            ds.previousSegment = ds.primarySegment;
            ds.primarySegment = d.segment;

            var oldPrice = ds.currentPrice;
            ds.currentPrice = Math.round((ds.currentPrice + d.priceChange) * 100) / 100;
            ds.currentPrice = Math.max(4.00, Math.min(12.00, ds.currentPrice));
            var priceChanged = (d.priceChange !== 0);
            var bigPriceChange = (Math.abs(d.priceChange) > 0.50);
            if (!priceChanged) {
                ds.roundsAtPrice += 1;
            } else {
                ds.roundsAtPrice = 0;
            }

            var channelActivationCost = 0;
            if (d.newChannel >= 0 && ds.activeChannels.indexOf(d.newChannel) < 0) {
                ds.activeChannels.push(d.newChannel);
                channelActivationCost = this.CHANNELS[d.newChannel].cost;
            }

            if (d.productAmount > 0 && d.productArea !== 'none') {
                if (d.productArea === 'formula') ds.hasNewFormula = true;
                if (d.productArea === 'packaging') ds.hasPackageUpgrade = true;
                if (d.productArea === 'certification' && !ds.hasCertification && ds.certRoundsLeft <= 0) {
                    ds.certRoundsLeft = 2;
                }
            }
            if (ds.certRoundsLeft > 0) {
                ds.certRoundsLeft -= 1;
                if (ds.certRoundsLeft <= 0) ds.hasCertification = true;
            }

            var beqChange = 0;
            if (d.budgetAwareness >= 15000) beqChange += 3;
            if (d.productAmount >= 8000) beqChange += 3;
            if (!priceChanged) beqChange += 2;
            if (ds.satisfaction >= 4.0) beqChange += 2;
            if (d.budgetLoyalty >= 5000) beqChange += 2;
            if (priceChanged && d.priceChange < 0) beqChange -= 3;
            if (segmentChanged) beqChange -= 8;
            if (bigPriceChange) beqChange -= 5;
            if (ds.satisfaction < 3.0) beqChange -= 4;

            ds.beq = Math.max(0, Math.min(100, ds.beq + beqChange));

            var channelFitCount = 0;
            for (var ci = 0; ci < ds.activeChannels.length; ci++) {
                if (seg.channels.indexOf(ds.activeChannels[ci]) >= 0) channelFitCount++;
            }
            var segmentFit = seg.channels.length > 0 ? channelFitCount / seg.channels.length : 0;

            var priceFit = 1 - Math.min(1, Math.abs(ds.currentPrice - seg.wtp) / seg.wtp);

            var totalBudgetSpent = d.budgetAwareness + d.budgetContent + d.budgetActivation + d.budgetLoyalty;
            var promoEfficiency = 0;
            if (totalBudgetSpent > 0) {
                promoEfficiency = (d.budgetAwareness * seg.aw + d.budgetContent * seg.co + d.budgetActivation * seg.ac + d.budgetLoyalty * seg.lo) / totalBudgetSpent;
            }

            var totalReach = 0;
            for (var ri = 0; ri < ds.activeChannels.length; ri++) {
                totalReach += this.CHANNELS[ds.activeChannels[ri]].reach;
            }
            totalReach = Math.min(1.0, totalReach);

            var beqFactor = ds.beq / 100;

            var productBonus = 0;
            if (ds.hasNewFormula) productBonus += 0.15;
            if (ds.hasPackageUpgrade) productBonus += 0.15;
            if (ds.hasCertification) productBonus += 0.20;

            var shareGrowth = segmentFit * 1.5 + priceFit * 1.0 + promoEfficiency * 1.5 + totalReach * 1.0 + beqFactor * 0.5 + productBonus;

            this._simulateCompetitors(state);

            var competitorPressure = 0.5;
            if (ds.marketShare > 8) competitorPressure += 0.3;
            if (ds.marketShare > 12) competitorPressure += 0.3;

            shareGrowth -= competitorPressure;
            if (segmentChanged) shareGrowth *= 0.6;

            var repositioningCost = 0;
            if (segmentChanged) repositioningCost = 5000;

            ds.marketShare = Math.round((ds.marketShare + shareGrowth) * 10) / 10;
            ds.marketShare = Math.max(1.0, Math.min(30.0, ds.marketShare));

            var eventEffect = this._applyEventEffect(state);

            var marketSizeUnits = 900000;
            var unitsSold = Math.round(marketSizeUnits * (ds.marketShare / 100));
            var grossRevenue = Math.round(unitsSold * ds.currentPrice);

            var avgMarginImpact = 0;
            for (var mi = 0; mi < ds.activeChannels.length; mi++) {
                avgMarginImpact += this.CHANNELS[ds.activeChannels[mi]].margin;
            }
            avgMarginImpact = avgMarginImpact / Math.max(1, ds.activeChannels.length);

            var costPerUnit = 3.50;
            var grossMarginPct = (ds.currentPrice - costPerUnit) / ds.currentPrice - avgMarginImpact;
            grossMarginPct = Math.max(0.02, Math.min(0.65, grossMarginPct));
            ds.grossMargin = Math.round(grossMarginPct * 100) / 100;
            ds.revenue = Math.round(grossRevenue * (1 - avgMarginImpact));

            var repeatBase = 31;
            var loyaltyEffect = Math.min(15, d.budgetLoyalty / 1500);
            var satisfactionEffect = (ds.satisfaction - 3.5) * 5;
            var beqRepeatEffect = ds.beq / 20;
            ds.repeatRate = Math.round(Math.max(10, Math.min(75, repeatBase + loyaltyEffect + satisfactionEffect + beqRepeatEffect)));

            ds.satisfaction = 3.5;
            if (priceFit > 0.7) ds.satisfaction += 0.3;
            if (ds.hasPackageUpgrade) ds.satisfaction += 0.2;
            if (ds.hasNewFormula) ds.satisfaction += 0.2;
            if (ds.hasCertification) ds.satisfaction += 0.1;
            if (promoEfficiency > 0.25) ds.satisfaction += 0.2;
            ds.satisfaction = Math.round(ds.satisfaction * 10) / 10;

            var totalCosts = channelActivationCost + d.productAmount + totalBudgetSpent + repositioningCost;
            var netProfit = ds.revenue - totalCosts - Math.round(unitsSold * costPerUnit);

            var channelEfficiency = totalBudgetSpent > 0 ? Math.round(ds.revenue / (totalBudgetSpent / 1000)) : 0;

            var coherence = 0;
            if (!segmentChanged || ds.previousSegment < 0) coherence += 3;
            if (!bigPriceChange) coherence += 3;
            if (segmentFit > 0.5) coherence += 2;
            if (priceFit > 0.6) coherence += 2;

            var shareScore = ds.marketShare >= 15 ? 25 : ds.marketShare >= 12 ? 20 : ds.marketShare >= 9 ? 15 : ds.marketShare >= 6 ? 10 : 5;
            var marginScore = Math.round(Math.min(20, ds.grossMargin * 30));
            var beqScore = Math.round(Math.min(20, ds.beq / 5));
            var repeatScore = Math.round(Math.min(15, ds.repeatRate / 5));
            var efficiencyScore = Math.round(Math.min(10, channelEfficiency / 200));
            var coherenceScore = coherence;
            var roundScore = shareScore + marginScore + beqScore + repeatScore + efficiencyScore + coherenceScore;

            ds.marketShareHistory.push(ds.marketShare);
            ds.beqHistory.push(ds.beq);
            ds.revenueHistory.push(ds.revenue);
            ds.scoreHistory.push(roundScore);

            ds.totalScore = 0;
            var weights = [0.25, 0.35, 0.40];
            for (var si = 0; si < ds.scoreHistory.length; si++) {
                ds.totalScore += ds.scoreHistory[si] * (weights[si] || 0.40);
            }
            ds.totalScore = Math.round(ds.totalScore * 10) / 10;

            // Grade contract: the Express grade adapter (results_utils.php ->
            // express_extractMetrics) reads ONLY domainState.performance.overallScore
            // and .grade. Without this block every recorded grade is 0.0/100.
            // overallScore mirrors the on-screen cumulative 'Puntaje' (ds.totalScore, 0-100);
            // the letter follows this sim's own performance tiers (see _perfTierKey).
            var overall = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            ds.performance = {
                overallScore: overall,
                grade: this._gradeLetter(overall),
                tier: this._perfTierKey(overall),
                insights: []
            };

            var results = {
                period: state.currentPeriod,
                marketShare: ds.marketShare,
                beq: ds.beq,
                revenue: ds.revenue,
                grossMargin: ds.grossMargin,
                repeatRate: ds.repeatRate,
                roundScore: roundScore,
                totalScore: ds.totalScore,
                shareGrowth: Math.round(shareGrowth * 10) / 10,
                beqChange: beqChange,
                channelCost: channelActivationCost,
                productCost: d.productAmount,
                netProfit: netProfit,
                eventEffect: eventEffect
            };

            // Briefing advance is driven by the framework's 'period:submitted' event
            // (see setupUI), which fires AFTER currentPeriod is incremented — so the
            // shown round always matches the current round. The old setTimeout read
            // the already-incremented currentPeriod and overshot by one (skipping Q2).
            return results;
        }

