        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function(k, v) { return k; };
            var lastResult = history[history.length - 1].results || {};
            var totalScore = lastResult.totalScore || 0;
            var finalShare = lastResult.marketShare || 0;
            var finalBEQ = lastResult.beq || 0;

            var tierKey = this._perfTierKey(totalScore);
            var msgKey = { tier_brilliant: 'msg_brilliant', tier_solid: 'msg_solid', tier_developing: 'msg_developing', tier_reorient: 'msg_reorient' }[tierKey];

            var insights = [];
            if (finalShare >= 15) {
                insights.push(t('insight_share_hit'));
            } else {
                insights.push(t('insight_share_miss', { share: finalShare.toFixed(1) }));
            }
            if (finalBEQ >= 60) {
                insights.push(t('insight_beq_strong'));
            } else if (finalBEQ >= 40) {
                insights.push(t('insight_beq_mid'));
            } else {
                insights.push(t('insight_beq_weak'));
            }

            return {
                totalScore: totalScore,
                finalMarketShare: finalShare,
                finalBEQ: finalBEQ,
                tier: tierKey,
                performance: t(tierKey),
                message: t(msgKey),
                insights: insights
            };
        }

        _gradeLetter(score) {
            if (score >= 85) return 'A';
            if (score >= 70) return 'B';
            if (score >= 55) return 'C';
            if (score >= 40) return 'D';
            return 'F';
        }

        _perfTierKey(score) {
            if (score >= 85) return 'tier_brilliant';
            if (score >= 70) return 'tier_solid';
            if (score >= 55) return 'tier_developing';
            return 'tier_reorient';
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            summary = summary || {};
            var score = Math.round(summary.totalScore || 0);
            var grade = this._gradeLetter(score);
            var tier = summary.performance || t(this._perfTierKey(score));
            var msg = summary.message || '';
            var insights = summary.insights || [];
            var lis = '';
            for (var i = 0; i < insights.length; i++) { lis += '<li>' + insights[i] + '</li>'; }
            return '' +
                '<div class="mktprimer-sim-completion text-center p-3">' +
                    '<h3 class="mktprimer-sim-completion-title">' + t('completion_heading') + '</h3>' +
