                    insight_share_hit:    `Objetivo del inversor de 15% de participación alcanzado — capital de crecimiento asegurado.`,
                    insight_share_miss:   `No se alcanzó la meta de 15% de participación. Final: {share}%. El inversor necesita más evidencia.`,
                    insight_beq_strong:   `Brand equity sólido construido en tres trimestres — una ventaja competitiva duradera.`,
                    insight_beq_mid:      `El brand equity crece pero necesita inversión sostenida y consistente.`,
                    insight_beq_weak:     `El brand equity sigue frágil. Las decisiones inconsistentes impidieron su acumulación.`,
                    completion_heading:   `Plan de Crecimiento Completado`,
                    completion_score:     `Puntaje Final`,
                    completion_grade:     `Nota`,
                    chart_share_title:    `Trayectoria de Participación`,
                    chart_beq_title:      `Brand Equity (BEQ)`,
                    chart_target:         `Meta 15%`,
                    select_option:        `-- Seleccionar --`
                }
            };
        }

        _simulateCompetitors(state) {
            var ds = state.domainState;
            var round = state.currentPeriod;

            if (round >= 2 && ds.marketShare > 8) {
                ds.qualibarShare = Math.max(12, ds.qualibarShare - 0.3);
                ds.qualibarBEQ = Math.min(80, ds.qualibarBEQ + 1);
            }
            if (round >= 3 && ds.beq > 50) {
                ds.qualibarPrice = Math.max(9.90, ds.qualibarPrice - 1.00);
                ds.qualibarShare += 0.5;
            }

            if (ds.activeChannels.indexOf(3) >= 0) {
                ds.fuerzaShare = Math.max(18, ds.fuerzaShare + 0.3);
                ds.fuerzaBEQ = Math.min(55, ds.fuerzaBEQ + 1);
            }
            if (round >= 3) {
                ds.fuerzaPrice = Math.max(3.90, ds.fuerzaPrice - 0.10);
                ds.fuerzaShare += 0.2;
            }

            var totalNamed = ds.marketShare + ds.qualibarShare + ds.fuerzaShare;
            if (totalNamed > 75) {
                var excess = totalNamed - 75;
                ds.qualibarShare = Math.max(10, ds.qualibarShare - excess * 0.4);
                ds.fuerzaShare = Math.max(15, ds.fuerzaShare - excess * 0.4);
            }
        }

        _applyEventEffect(state) {
            var ds = state.domainState;
            var d = state.decisions;
            if (d.eventChoice < 0) return '';

            var round = state.currentPeriod;
            var eventId = this._getActiveEventId(round, ds);
            if (eventId < 0) return '';

            var effect = '';
            if (eventId === 0) {
                if (d.eventChoice === 0) {
                    ds.marketShare += 2.5;
                    effect = '+2.5pp market share (extra S/. 10,000 cost)';
                } else if (d.eventChoice === 1) {
                    ds.marketShare += 1.8;
                    ds.beq -= 2;
                    effect = '+1.8pp share, BEQ −2';
                } else {
                    ds.marketShare += 0.5;
                    effect = '+0.5pp passive spillover';
                }
            } else if (eventId === 1) {
                if (d.eventChoice === 0) {
                    ds.marketShare += 1.0;
                    ds.beq += 2;
                    effect = '+1.0pp share, +2 BEQ (extra S/. 8,000 cost)';
                } else if (d.eventChoice === 1) {
                    ds.marketShare += 0.4;
                    ds.beq += 1;
                    effect = '+0.4pp share, +1 BEQ';
                } else {
                    effect = 'Trend passed without brand participation';
                }
            } else if (eventId === 2) {
                if (d.eventChoice === 0) {
                    ds.currentPrice = 5.90;
                    ds.beq -= 3;
                    ds.marketShare += 1.0;
                    effect = 'Price cut to S/. 5.90, BEQ −3, +1.0pp share';
                } else if (d.eventChoice === 1) {
                    ds.beq += 4;
                    ds.marketShare += 0.5;
                    effect = '+4 BEQ, +0.5pp share (extra S/. 12,000 cost)';
                } else {
                    ds.beq += 2;
                    ds.marketShare += 0.8;
                    effect = 'Line extension launched, +2 BEQ, +0.8pp share';
                }
            }

            ds.triggeredEvents.push(eventId);
            return effect;
        }

        _getActiveEventId(round, ds) {
            if (!ds || !ds.eventSeed) return -1;
            var s = ds.eventSeed;
            var triggered = ds.triggeredEvents || [];

            if (round === 1) {
                if (s < 0.20 && triggered.indexOf(1) < 0) return 1;
            } else if (round === 2) {
                if (s > 0.30 && s < 0.60 && triggered.indexOf(0) < 0) return 0;
                if (s >= 0.60 && s < 0.80 && triggered.indexOf(1) < 0) return 1;
            } else if (round === 3) {
                if (s > 0.10 && s < 0.50 && triggered.indexOf(2) < 0) return 2;
            }
            return -1;
        }

        _updateBriefing(state) {
            var round = Math.min((state.currentPeriod || 1), 3);
            var idx = round - 1;
            var ds = state.domainState || {};
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                titleEl.innerHTML = 'Q' + round + ': ' + t('round' + round + '_title');
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = t('round' + round + '_brief');
            }

            var channelDisplay = document.getElementById('activeChannelsDisplay');
            if (channelDisplay && ds.activeChannels) {
                var names = [t('ch_name_0'), t('ch_name_1'), t('ch_name_2'), t('ch_name_3'), t('ch_name_4')];
                var activeNames = [];
                for (var ni = 0; ni < ds.activeChannels.length; ni++) {
                    activeNames.push(names[ds.activeChannels[ni]] || '');
                }
                var labelText = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t('active_channels') : 'Canales activos';
                channelDisplay.innerHTML = '<small>' + labelText + ': ' + activeNames.join(', ') + '</small>';
            }

            var chSelect = document.getElementById('channelSelect');
            if (chSelect && ds.activeChannels) {
                var options = chSelect.querySelectorAll('option');
                for (var oi = 0; oi < options.length; oi++) {
                    var val = parseInt(options[oi].value);
                    if (val >= 0) {
                        options[oi].disabled = (ds.activeChannels.indexOf(val) >= 0);
                    }
                }
            }

            var eventId = this._getActiveEventId(round, ds);
            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) {
                if (eventId >= 0) {
                    eventPanel.style.display = 'block';
                    var tPrefix = 'event' + (eventId + 1);
                    var evTitle = document.getElementById('eventTitle');
                    var evDesc = document.getElementById('eventDescription');
                    var evSelect = document.getElementById('eventChoiceSelect');

                    if (evTitle) evTitle.textContent = t(tPrefix + '_title');
                    if (evDesc) evDesc.textContent = t(tPrefix + '_desc');
                    if (evSelect) {
                        evSelect.innerHTML = '<option value="-1">' + t('select_option') + '</option>' +
                            '<option value="0">' + t(tPrefix + '_a') + '</option>' +
                            '<option value="1">' + t(tPrefix + '_b') + '</option>' +
                            '<option value="2">' + t(tPrefix + '_c') + '</option>';
                    }
                } else {
                    eventPanel.style.display = 'none';
                }
            }

            if (!this._listenersAttached) {
                var budgetInputs = document.querySelectorAll('.budget-input');
                if (budgetInputs.length > 0) {
                    var updateBudgetDisplay = function() {
                        var total = 0;
                        for (var bi = 0; bi < budgetInputs.length; bi++) {
                            total += parseInt(budgetInputs[bi].value) || 0;
                        }
                        var display = document.getElementById('budgetAllocatedDisplay');
                        if (display) {
                            display.textContent = 'S/. ' + total.toLocaleString();
                            if (total > 45000) {
                                display.style.color = '#e74c3c';
                            } else if (total === 45000) {
                                display.style.color = '#27ae60';
                            } else {
                                display.style.color = '#f39c12';
                            }
                        }
                    };
                    for (var li = 0; li < budgetInputs.length; li++) {
                        budgetInputs[li].addEventListener('input', updateBudgetDisplay);
                    }
                    updateBudgetDisplay();
                    this._listenersAttached = true;
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new MarketingPrimerAdapter(), {
            simulationType: 'marketing_primer_288',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
